import { useEffect, useRef } from "react";

import coverUrl from "@/assets/audio/background-swiss-keepsakes-cover.jpg?url";
import trackUrl from "@/assets/audio/background-swiss-keepsakes.mp3?url";
import {
  getMusic,
  musicControls,
  setMusic,
  useMusic,
} from "@/components/background-music-store";
import { MusicLauncher } from "@/components/music-launcher";
import { MusicSheet } from "@/components/music-sheet";
import { useLocale } from "@/contexts/locale-context";

const FADE_MS = 800;
const GESTURES = ["pointerdown", "keydown", "touchend"] as const;

const reducedMotion = () =>
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/** True while the guest has started a YouTube embed (its player is cross-origin: no media events reach us). */
const videoEmbedOpen = () =>
  document.querySelector('iframe[src*="youtube"]') !== null;

/**
 * Looping background track for the guest app (owner request, 16.10.2026). Mounted once by
 * GuestShell, which stays mounted across guest routes, so the track never restarts when
 * the guest moves between screens or opens the player sheet.
 *
 * Browsers refuse sound before a gesture: the first play() may reject with NotAllowedError.
 * Then one-shot listeners wait for the first real gesture and start it; nothing is shown.
 * Pause in the player (or on a headset) is the guest's "off": remembered, and never overridden by autoplay.
 * The track yields to a hidden tab and to any other media (story audio, video embeds).
 * `showDock` places the launcher in the trip assistant's slot on screens without that button.
 */
export function BackgroundMusic({ showDock }: { showDock: boolean }) {
  const audioRef = useRef<HTMLAudioElement>(null);
  const { stacked } = useMusic();
  const { t } = useLocale();

  useEffect(() => {
    const audio = audioRef.current;

    if (!audio) return;

    const others = new Set<HTMLMediaElement>();
    let fade = 0;
    let armed = false;
    // The track is not requested until the page has finished loading, so it never competes with first paint.
    let ready = false;

    const target = () => {
      const { level, muted } = getMusic();

      return muted ? 0 : level;
    };

    const otherMediaPlaying = () => {
      // An element removed while playing (leaving a story) never sends a pause event we can hear.
      for (const el of others) {
        if (!el.isConnected || el.paused || el.ended) others.delete(el);
      }

      return others.size > 0 || videoEmbedOpen();
    };

    const fadeTo = (goal: number, done?: () => void) => {
      clearInterval(fade);
      if (reducedMotion() || document.hidden) {
        audio.volume = goal;
        done?.();

        return;
      }
      const from = audio.volume;
      const ms = (FADE_MS * Math.abs(goal - from)) / (getMusic().level || 1);
      const start = performance.now();

      // A timer, not requestAnimationFrame: frames stop in a background or occluded view.
      fade = window.setInterval(() => {
        const k = ms === 0 ? 1 : Math.min(1, (performance.now() - start) / ms);

        audio.volume = from + (goal - from) * k;
        if (k < 1) return;
        clearInterval(fade);
        done?.();
      }, 40);
    };

    const onGesture = (e: Event) => {
      // The player's own controls decide for themselves what a tap means.
      if ((e.target as Element | null)?.closest?.("[data-music-ui]")) return;
      sync();
    };
    const arm = () => {
      if (armed) return;
      armed = true;
      for (const type of GESTURES)
        document.addEventListener(type, onGesture, {
          capture: true,
          passive: true,
        });
    };
    const disarm = () => {
      if (!armed) return;
      armed = false;
      for (const type of GESTURES)
        document.removeEventListener(type, onGesture, { capture: true });
    };

    const wanted = () => {
      return getMusic().enabled && !document.hidden && !otherMediaPlaying();
    };

    const silence = () => audio.pause();

    function sync(force = false) {
      if (!ready && !force) return;
      if (!wanted()) {
        disarm();
        if (!audio!.paused) fadeTo(0, silence);

        return;
      }
      if (!audio!.paused) {
        fadeTo(target());

        return;
      }
      audio!.volume = 0;
      audio!.play().then(
        () => {
          setMusic({ blocked: false });
          disarm();
          // The world may have changed while the request was in flight.
          if (wanted()) fadeTo(target());
          else audio!.pause();
        },
        (error: unknown) => {
          if (
            error instanceof DOMException &&
            error.name === "NotAllowedError"
          ) {
            setMusic({ blocked: true });
            arm();
          }
          // AbortError (paused mid-request) and a missing or broken file stay silent.
        },
      );
    }

    musicControls.audio = audio;
    musicControls.play = () => {
      setMusic({ enabled: true });
      sync(true);
    };
    musicControls.pause = () => {
      setMusic({ enabled: false });
      sync(true);
    };
    musicControls.seek = (seconds) => {
      audio.currentTime = seconds;
    };
    musicControls.setLevel = (level) => {
      setMusic({ level, muted: false });
      clearInterval(fade);
      if (!audio.paused) audio.volume = level;
    };
    musicControls.toggleMute = () => {
      setMusic({ muted: !getMusic().muted });
      clearInterval(fade);
      if (!audio.paused) audio.volume = target();
    };
    musicControls.loadMetadata = () => {
      // Seeking and the length label need the file's header, not the whole file.
      if (Number.isFinite(audio.duration) || !audio.paused) return;
      audio.preload = "metadata";
      audio.load();
    };

    const onMedia = (e: Event) => {
      const el = e.target;

      if (!(el instanceof HTMLMediaElement) || el === audio) return;
      if (e.type === "play") others.add(el);
      else others.delete(el);
      sync();
    };
    const mediaEvents = ["play", "pause", "ended"] as const;
    const onOwnPlayback = () => setMusic({ playing: !audio.paused });
    const onVisibility = () => sync();

    // Lock-screen and headset controls go through the same paths as the sheet, so they persist the same way.
    const session = "mediaSession" in navigator ? navigator.mediaSession : null;
    const skipBy = (delta: number) => {
      if (Number.isFinite(audio.duration))
        audio.currentTime = Math.min(
          Math.max(audio.currentTime + delta, 0),
          audio.duration,
        );
    };
    const handlers: [MediaSessionAction, MediaSessionActionHandler][] = [
      ["play", () => musicControls.play()],
      ["pause", () => musicControls.pause()],
      [
        "seekto",
        (d) => {
          if (typeof d.seekTime === "number") audio.currentTime = d.seekTime;
        },
      ],
      ["seekbackward", (d) => skipBy(-(d.seekOffset ?? 10))],
      ["seekforward", (d) => skipBy(d.seekOffset ?? 10)],
    ];

    if (session) {
      try {
        session.metadata = new MediaMetadata({
          title: "Swiss Keepsakes",
          artwork: [{ src: coverUrl, sizes: "256x256", type: "image/jpeg" }],
        });
      } catch {
        // No MediaMetadata: the controls still work without a title.
      }
      for (const [action, handler] of handlers) {
        try {
          session.setActionHandler(action, handler);
        } catch {
          // An action this browser does not know.
        }
      }
    }

    for (const type of mediaEvents)
      document.addEventListener(type, onMedia, true);
    audio.addEventListener("play", onOwnPlayback);
    audio.addEventListener("pause", onOwnPlayback);
    document.addEventListener("visibilitychange", onVisibility);
    // Catches an embed opening or a player leaving the page, neither of which fires on document.
    let frame = 0;
    const observer = new MutationObserver(() => {
      clearTimeout(frame);
      frame = window.setTimeout(() => {
        if (!armed && wanted() === audio.paused) sync();
      }, 50);
    });

    observer.observe(document.body, { childList: true, subtree: true });

    let idle = 0;
    const begin = () => {
      idle = window.setTimeout(() => {
        ready = true;
        sync();
      }, 300);
    };

    if (document.readyState === "complete") begin();
    else window.addEventListener("load", begin, { once: true });

    return () => {
      for (const type of mediaEvents)
        document.removeEventListener(type, onMedia, true);
      audio.removeEventListener("play", onOwnPlayback);
      audio.removeEventListener("pause", onOwnPlayback);
      document.removeEventListener("visibilitychange", onVisibility);
      if (session) {
        session.metadata = null;
        for (const [action] of handlers) {
          try {
            session.setActionHandler(action, null);
          } catch {
            // An action this browser does not know.
          }
        }
      }
      window.removeEventListener("load", begin);
      observer.disconnect();
      clearTimeout(idle);
      clearTimeout(frame);
      clearInterval(fade);
      disarm();
      audio.pause();
      Object.assign(musicControls, {
        audio: null,
        play: () => {},
        pause: () => {},
        seek: () => {},
        setLevel: () => {},
        toggleMute: () => {},
        loadMetadata: () => {},
      });
    };
  }, []);

  return (
    <>
      {/* Decorative loop with no speech: captions do not apply. */}
      {/* eslint-disable-next-line jsx-a11y/media-has-caption */}
      <audio
        ref={audioRef}
        loop
        aria-label={t("music.title")}
        preload="none"
        src={trackUrl}
      />
      <MusicSheet />
      {showDock && stacked === 0 && (
        <div className="pointer-events-none fixed inset-x-0 bottom-[calc(env(safe-area-inset-bottom,0px)+72px)] z-20 mx-auto flex max-w-[430px] justify-end px-4">
          <MusicLauncher />
        </div>
      )}
    </>
  );
}

import { AlertDialog, Button } from "@heroui/react";
import { useCallback, useEffect, useRef, useState } from "react";

import { useLocale } from "@/contexts/locale-context";

export interface ConfirmOptions {
  /** A question naming the thing: "Remove Pocket knife · M?". */
  title: string;
  /** One sentence saying what happens, with the money consequence if there is one. */
  body: string;
  /** Names the action, never "OK" or "Yes": "Remove from cart", "Cancel order". */
  confirmLabel: string;
  /** Defaults to "Cancel" (`confirm.cancel`). */
  cancelLabel?: string;
  /** `danger` (default): soft brick icon and the ink destructive button. */
  tone?: "danger";
}

export interface ConfirmDialogProps extends ConfirmOptions {
  isOpen: boolean;
  onConfirm: () => void;
  /** Cancel button, Esc or a backdrop tap. */
  onCancel: () => void;
}

/**
 * Shared confirmation before every delete, remove or cancel action (owner rule,
 * 13.10.2026). Design-system AlertDialog card: bottom-anchored card on phones, centred
 * from `sm`; focus starts on Cancel; Esc and a backdrop tap cancel. On phones the
 * buttons stack full width with the destructive one on top (German labels do not fit
 * side by side at 375px, and labels never wrap).
 *
 * Controlled; most callers want {@link useConfirm} instead:
 *
 * ```tsx
 * <ConfirmDialog
 *   isOpen={open}
 *   title={t("orders.cancel.title")}
 *   body={t("orders.cancel.body", { amount })}
 *   confirmLabel={t("orders.cancel.confirm")}
 *   onCancel={() => setOpen(false)}
 *   onConfirm={() => { cancelOrder(); setOpen(false); }}
 * />
 * ```
 */
export function ConfirmDialog({
  isOpen,
  title,
  body,
  confirmLabel,
  cancelLabel,
  tone = "danger",
  onConfirm,
  onCancel,
}: ConfirmDialogProps) {
  const { t } = useLocale();

  return (
    <AlertDialog.Backdrop
      isDismissable
      isKeyboardDismissDisabled={false}
      isOpen={isOpen}
      onOpenChange={(open) => !open && onCancel()}
    >
      <AlertDialog.Container size="sm">
        <AlertDialog.Dialog>
          <AlertDialog.Header>
            <AlertDialog.Icon status={tone} />
            <AlertDialog.Heading>{title}</AlertDialog.Heading>
          </AlertDialog.Header>
          <AlertDialog.Body>
            <p>{body}</p>
          </AlertDialog.Body>
          <AlertDialog.Footer className="flex-col-reverse sm:flex-row">
            <Button
              // WAI-ARIA alertdialog: focus starts on the least destructive action.
              // eslint-disable-next-line jsx-a11y/no-autofocus
              autoFocus
              className="w-full sm:w-auto"
              variant="tertiary"
              onPress={onCancel}
            >
              {cancelLabel ?? t("confirm.cancel")}
            </Button>
            <Button
              className="w-full sm:w-auto"
              variant={tone}
              onPress={onConfirm}
            >
              {confirmLabel}
            </Button>
          </AlertDialog.Footer>
        </AlertDialog.Dialog>
      </AlertDialog.Container>
    </AlertDialog.Backdrop>
  );
}

/**
 * Asks before a destructive action. Render `dialog` once anywhere in the component, then
 * `await confirm(options)`: true after the confirm button, false after Cancel, Esc, a
 * backdrop tap or unmount.
 *
 * ```tsx
 * const { confirm, dialog } = useConfirm();
 *
 * const onRemove = async () => {
 *   if (await confirm({ title, body, confirmLabel })) remove(id);
 * };
 *
 * return <>{list}{dialog}</>;
 * ```
 */
export function useConfirm() {
  const [options, setOptions] = useState<ConfirmOptions | null>(null);
  const [isOpen, setIsOpen] = useState(false);
  const resolveRef = useRef<((confirmed: boolean) => void) | null>(null);

  const settle = useCallback((confirmed: boolean) => {
    resolveRef.current?.(confirmed);
    resolveRef.current = null;
    setIsOpen(false);
  }, []);

  const confirm = useCallback(
    (next: ConfirmOptions) =>
      new Promise<boolean>((resolve) => {
        resolveRef.current?.(false);
        resolveRef.current = resolve;
        setOptions(next);
        setIsOpen(true);
      }),
    [],
  );

  useEffect(() => () => resolveRef.current?.(false), []);

  // The options stay after closing so the text does not vanish during the exit animation.
  const dialog = options ? (
    <ConfirmDialog
      {...options}
      isOpen={isOpen}
      onCancel={() => settle(false)}
      onConfirm={() => settle(true)}
    />
  ) : null;

  return { confirm, dialog };
}

import type { ProductCardProps } from "./product-card";
import type { Key } from "@heroui/react";

import { useState } from "react";
import {
  ScrollShadow,
  SearchField,
  Skeleton,
  Tag,
  TagGroup,
} from "@heroui/react";

import { CategoryThumb, categoryThumbItemClass } from "./category-thumb";
import { ProductCard } from "./product-card";

import { EmptyState } from "@/components/empty-state";
import { GiftIcon } from "@/components/icons";
import {
  BackButton,
  CartButton,
  CompactBar,
  SearchButton,
} from "@/components/layout/cart-button";
import { Media } from "@/components/media";
import { useScrolledPast } from "@/hooks/use-scrolled-past";

export const ALL_CATEGORIES = "all";

interface GiftListProps {
  banner: {
    title: string;
    tagline: string;
    countLabel: string;
    photo?: string;
  };
  search: {
    /** Scope label, e.g. "Search in Gift boxes"; also the field's accessible name. */
    label: string;
    openLabel: string;
    backLabel: string;
    value: string;
    onChange: (v: string) => void;
  };
  filter: {
    label: string;
    items: { id: string; name: string; photo?: string }[];
    selected: string;
    onChange: (id: string) => void;
  };
  cards: ProductCardProps[];
  empty: { message: string; actionLabel: string } | null;
  isLoading: boolean;
}

/**
 * C02 Gifts, native-app layout: a full-bleed photo banner for the selected category,
 * then a sheet with photo category tiles (a single-selection TagGroup; selected = red ring
 * plus check badge, never hue alone) and the shared gift cards, one per row (owner: few products, larger photos). Search is scoped
 * to this screen and works like a native nav-bar search: 🔍 (on the banner or the
 * collapsing bar) turns the top bar into ← back + the search field in place, pinned at the
 * current scroll position, and the grid filters live underneath. Back clears it and
 * restores the bar.
 */
export function GiftList({
  banner,
  search,
  filter,
  cards,
  empty,
  isLoading,
}: GiftListProps) {
  const [searchOpen, setSearchOpen] = useState(search.value !== "");
  const [bannerEnd, scrolledPast] = useScrolledPast<HTMLDivElement>();

  const openSearch = () => setSearchOpen(true);

  const closeSearch = () => {
    search.onChange("");
    setSearchOpen(false);
  };

  const onSelectionChange = (keys: "all" | Set<Key>) => {
    const [first] = keys === "all" ? [] : [...keys];

    // Single selection never clears: tapping the selected tile keeps it selected.
    if (first !== undefined) filter.onChange(String(first));
  };

  return (
    <div className="flex flex-col">
      {searchOpen ? (
        <CompactBar visible>
          <BackButton label={search.backLabel} onPress={closeSearch} />
          <SearchField
            // Opened on purpose by the 🔍 action, so the keyboard comes up.
            // eslint-disable-next-line jsx-a11y/no-autofocus
            autoFocus
            aria-label={search.label}
            className="flex-1"
            value={search.value}
            onChange={search.onChange}
          >
            <SearchField.Group>
              <SearchField.SearchIcon />
              <SearchField.Input
                className="w-full"
                placeholder={search.label}
              />
              <SearchField.ClearButton />
            </SearchField.Group>
          </SearchField>
        </CompactBar>
      ) : (
        <CompactBar title={banner.title} visible={scrolledPast}>
          <SearchButton
            label={search.openLabel}
            tone="bar"
            onPress={openSearch}
          />
          <CartButton tone="bar" />
        </CompactBar>
      )}
      <Media alt="" className="h-[260px]" photo={banner.photo}>
        <div
          aria-hidden
          className="absolute inset-0 bg-gradient-to-b from-black/30 via-black/10 to-black/70"
        />
        {/* Actions top right (owner: no logo here, 13.10.2026). While searching, the top
            bar holds the field and the banner's own row steps aside. */}
        {!searchOpen && (
          <div className="absolute inset-x-4 top-[calc(env(safe-area-inset-top,0px)+12px)] flex items-center justify-end gap-2">
            <SearchButton label={search.openLabel} onPress={openSearch} />
            <CartButton />
          </div>
        )}
        <div className="absolute inset-x-4 bottom-10 flex flex-col gap-1 text-white">
          <h1 className="font-serif text-display">{banner.title}</h1>
          <p className="text-body text-white/85">{banner.tagline}</p>
          <p className="text-label text-white/85 tabular-nums">
            {banner.countLabel}
          </p>
        </div>
      </Media>
      <div ref={bannerEnd} aria-hidden className="h-px" />

      <div className="relative -mt-6 flex flex-col gap-5 rounded-t-3xl bg-background px-4 pt-5 pb-4">
        <TagGroup
          aria-label={filter.label}
          selectedKeys={new Set([filter.selected])}
          selectionMode="single"
          onSelectionChange={onSelectionChange}
        >
          <ScrollShadow
            hideScrollBar
            className="-mx-4"
            orientation="horizontal"
            size={40}
          >
            <TagGroup.List className="flex-nowrap gap-1 px-4 pt-2 pb-1">
              {filter.items.map((item) => (
                <Tag
                  key={item.id}
                  className={`${categoryThumbItemClass} bg-transparent p-0 before:hidden hover:bg-transparent data-[selected=true]:bg-transparent data-[selected=true]:font-semibold data-[selected=true]:text-foreground`}
                  id={item.id}
                  textValue={item.name}
                >
                  <CategoryThumb name={item.name} photo={item.photo} />
                </Tag>
              ))}
            </TagGroup.List>
          </ScrollShadow>
        </TagGroup>

        {isLoading ? (
          <ul className="flex flex-col gap-7">
            {Array.from({ length: 3 }, (_, i) => (
              <li key={i} className="flex flex-col gap-2.5">
                <Skeleton className="aspect-[4/3] rounded-3xl" />
                <Skeleton className="h-5 w-4/5 rounded-lg" />
                <Skeleton className="h-4 w-3/5 rounded-lg" />
              </li>
            ))}
          </ul>
        ) : empty ? (
          <EmptyState
            action={{ label: empty.actionLabel, to: "/gifts" }}
            icon={GiftIcon}
            message={empty.message}
          />
        ) : (
          <ul className="flex flex-col gap-7">
            {cards.map((card) => (
              <li key={card.slug}>
                <ProductCard {...card} layout="grid" />
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

import type { CalendarDate, DateValue } from "@internationalized/date";

import { Calendar } from "@heroui/react";
import { useId, useState } from "react";

export interface PickupDateFieldProps {
  label: string;
  /** "Earliest Fri 16 Oct". */
  description: string;
  /** Demo-clock today: past days are disabled (struck through), per the Calendar card. */
  today: CalendarDate;
  /** First valid pickup day; the calendar opens on its month. */
  earliest: CalendarDate;
  /** Days still being prepared or closed: pale (unavailable), not disabled. */
  isUnavailable: (date: DateValue) => boolean;
  /** Why a pale day cannot be picked (YYYY-MM-DD), shown when the guest taps it. */
  reasonFor: (isoDate: string) => string | undefined;
  legend: { title: string; prep: string; closed: string };
  value: CalendarDate | null;
  onChange: (value: CalendarDate) => void;
  error?: string;
}

const paleDot = (
  <span
    aria-hidden
    className="mt-[5px] size-2 shrink-0 rounded-full bg-foreground opacity-50"
  />
);

/**
 * Pickup date on C03, picked on an inline calendar inside the add-to-cart sheet
 * (Airbnb pattern; Calendar card). Pale days carry their reason in the legend.
 */
export function PickupDateField({
  label,
  description,
  today,
  earliest,
  isUnavailable,
  reasonFor,
  legend,
  value,
  onChange,
  error,
}: PickupDateFieldProps) {
  const labelId = useId();
  const helpId = useId();
  const [tapped, setTapped] = useState<string>();
  const message = tapped ?? error;

  // React Aria ignores presses on unavailable days; answer them with the reason
  // (Calendar card: a tapped closed day gets an error message).
  // Unavailable cells have pointer-events: none (HeroUI), so a tap lands on their <td>.
  const explain = (target: EventTarget) => {
    const el = target as HTMLElement;
    const selector = '[data-unavailable="true"][data-date]';
    const cell =
      el.closest<HTMLElement>(selector) ??
      el.closest("td")?.querySelector<HTMLElement>(selector);

    if (cell?.dataset.date) setTapped(reasonFor(cell.dataset.date));
  };

  return (
    // Click and Enter only explain pale days; picking stays with the calendar grid.
    // eslint-disable-next-line jsx-a11y/no-static-element-interactions
    <div
      className="flex flex-col gap-3"
      id="gift-date"
      onClick={(e) => explain(e.target)}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") explain(e.target);
      }}
    >
      <div className="flex flex-col gap-0.5">
        <span className="text-heading font-medium text-foreground" id={labelId}>
          {label}
        </span>
        <span className="text-sm text-muted" id={helpId}>
          {description}
        </span>
      </div>
      <Calendar
        aria-describedby={helpId}
        aria-labelledby={labelId}
        className="calendar--fluid"
        defaultFocusedValue={earliest}
        isDateUnavailable={isUnavailable}
        isInvalid={error !== undefined}
        minValue={today}
        value={value}
        onChange={(v) => {
          setTapped(undefined);
          onChange(v);
        }}
      >
        <Calendar.Header>
          <Calendar.Heading />
          <Calendar.NavButton slot="previous" />
          <Calendar.NavButton slot="next" />
        </Calendar.Header>
        <Calendar.Grid>
          <Calendar.GridHeader>
            {(day) => <Calendar.HeaderCell>{day}</Calendar.HeaderCell>}
          </Calendar.GridHeader>
          <Calendar.GridBody>
            {(date) => (
              <Calendar.Cell
                // React Aria marks the real today; the prototype marks the demo today.
                className={
                  date.compare(today) === 0 ? "calendar__cell--demo-today" : ""
                }
                data-date={date.toString()}
                date={date}
              />
            )}
          </Calendar.GridBody>
        </Calendar.Grid>
      </Calendar>
      <div className="flex flex-col gap-1 text-xs text-muted">
        <p className="font-medium text-foreground">{legend.title}</p>
        <p className="flex gap-2">
          {paleDot}
          {legend.prep}
        </p>
        <p className="flex gap-2">
          {paleDot}
          {legend.closed}
        </p>
      </div>
      {message && (
        <p data-visible className="field-error" role="alert">
          {message}
        </p>
      )}
    </div>
  );
}

import type { ArticleBlock } from "../types";

import { ProgressBar } from "@heroui/react";
import { useEffect, useRef, useState } from "react";

