import type { RowAction } from "@/components/row-actions";

import { LanguageChip, MaintenanceChip, PublishChip } from "./status-chips";

import { ArchiveIcon, EditIcon, RestoreIcon } from "@/components/icons";
import { DataTable } from "@/components/data-table";
import { RowActions } from "@/components/row-actions";
import { Media } from "@/components/media";
import { StatusChip } from "@/components/status-chip";
import { useLocale } from "@/contexts/locale-context";

export type ProductAction = "edit" | "archive" | "restore";

interface ProductRowsProps {
  rows: ProductRow[];
  /** Accessible name of the list or table: the selected tab. */
  label: string;
  /** Table headers: name, status, then the three facts. */
  columns: [string, string, string, string, string];
  onAction: (row: ProductRow, action: ProductAction) => void;
  /** Shown inside the table (a card on phones) when `rows` is empty. */
  empty?: EmptyStateProps;
  /** Back to page 1 when this changes. */
  resetKey?: string;
  isLoading?: boolean;
}

/** Edit and archive (or restore), in a ⋯ menu as on M15, so a tap on a row never archives. */
function MoreMenu({
  row,
  onAction,
}: {
  row: ProductRow;
  onAction: ProductRowsProps["onAction"];
}) {
  const { t } = useLocale();
  const actions: RowAction<ProductAction>[] = [
    { id: "edit", label: t("products.action.edit"), icon: EditIcon },
    row.archived
      ? {
          id: "restore",
          label: t("products.action.restore"),
          icon: RestoreIcon,
        }
      : {
          id: "archive",
          label: t("products.action.archive"),
          icon: ArchiveIcon,
        },
  ];

  return (
    <RowActions
      actions={actions}
      label={t("products.action.more", { name: row.name })}
      onAction={(id) => onAction(row, id)}
    />
  );
}

/** "Archived" in place of the publish chip. */
function StateChip({ row }: { row: ProductRow }) {
  const { t } = useLocale();

  return row.archived ? (
    <StatusChip tone="neutral">{t("products.archived")}</StatusChip>
  ) : (
    <>
      <PublishChip published={row.published} />
      {row.maintenance && <MaintenanceChip />}
    </>
  );
}

/**
 * Phones: one card per gift or tour in the M03 ticket shape (1.10b/c). Photo, name and meta
 * where M03 has the date tile and guest; the publish and language chips; the price,
 * availability and commission in the dashed footer, one fact per row. The card opens M12/M13.
 */
function StackedRows({ rows, label, onAction }: ProductRowsProps) {
  return (
    <ul aria-label={label} className="flex flex-col gap-5 lg:hidden">
      {rows.map((row) => (
        <li key={row.id}>
          <article className="relative flex flex-col overflow-hidden rounded-3xl bg-surface shadow-surface card-hover">
            <div className="flex items-center gap-4 p-4">
              <Media
                alt=""
                className="size-14 shrink-0 rounded-lg"
                photo={row.photo}
              />
              <div className="min-w-0 flex-1">
                <h3 className="text-lg leading-tight font-semibold break-words hyphens-auto">
                  {/* The whole card opens M12/M13; the menu sits above the stretched link. */}
                  <a
                    className="rounded-md outline-none after:absolute after:inset-0 focus-visible:focus-ring"
                    href={row.href}
                  >
                    {row.name}
                  </a>
                </h3>
                <p className="mt-2 text-xs text-muted">{row.meta}</p>
              </div>
              <div className="relative shrink-0">
                <MoreMenu row={row} onAction={onAction} />
              </div>
            </div>
            <div className="flex flex-wrap gap-2 px-4 pb-4 [&_svg]:shrink-0">
              <StateChip row={row} />
              <LanguageChip status={row.languages} />
            </div>
            <dl className="flex flex-col gap-2 border-t border-dashed border-separator px-4 py-3.5 text-sm">
              {row.facts.map((fact, index) => (
                <div
                  key={fact.label}
                  className="flex items-baseline justify-between gap-4"
                >
                  <dt className="shrink-0 text-muted">{fact.label}</dt>
                  <dd
                    className={`text-end tabular-nums ${
                      fact.isWarning
                        ? "text-warning"
                        : index === 0
                          ? "font-semibold"
                          : "text-muted"
                    }`}
                  >
                    {fact.value}
                  </dd>
                </div>
              ))}
            </dl>
          </article>
        </li>
      ))}
    </ul>
  );
}

export function ProductRows(props: ProductRowsProps) {
  const { columns: names, onAction } = props;
  const columns: DataTableColumn<ProductRow>[] = [
    {
      id: "name",
      header: names[0],
      headerClassName: "w-[36%]",
      isRowHeader: true,
      skeleton: "lead",
      render: (row) => (
        <div className="flex items-center gap-3">
          <Media
            alt=""
            className="size-10 shrink-0 rounded-lg"
            photo={row.photo}
          />
          <div className="flex min-w-0 flex-col">
            <a
              className="font-semibold break-words underline-offset-4 outline-none hover:underline focus-visible:focus-ring"
              href={row.href}
            >
              {row.name}
            </a>
            <span className="text-label text-muted">{row.meta}</span>
          </div>
        </div>
      ),
    },
    {
      id: "status",
      header: names[1],
      headerClassName: "w-[19%]",
      skeleton: "chip",
      cellClassName: "py-2",
      render: (row) => (
        <div className="flex flex-col items-start gap-1.5 [&_svg]:shrink-0">
          <StateChip row={row} />
          <LanguageChip status={row.languages} />
        </div>
      ),
    },
    ...[2, 3, 4].map((fact) => ({
      id: `fact-${fact}`,
      header: names[fact],
      headerClassName: fact === 4 ? "w-[12%]" : "w-[13%]",
      cellClassName: (row: ProductRow) =>
        `whitespace-nowrap tabular-nums ${row.facts[fact - 2]?.isWarning ? "text-warning" : ""}`,
      render: (row: ProductRow) => row.facts[fact - 2]?.value,
    })),
  ];

  return (
    // No row link: a press in the ⋯ menu would also open the row (as on M15).
    <DataTable
      cards={(page) => <StackedRows {...props} rows={page} />}
      columns={columns}
      contentClassName="table-fixed"
      empty={props.empty}
      getRowId={(row) => row.id}
      isLoading={props.isLoading}
      label={props.label}
      resetKey={props.resetKey}
      rowActions={{
        render: (row) => <MoreMenu row={row} onAction={onAction} />,
        headerClassName: "w-[7%]",
      }}
      rows={props.rows}
    />
  );
}

import type { CollectStatus, TodayTaskId } from "../lib/today";
import type { IconComponent } from "@/components/icons";
import type { StatusTone } from "@/components/status-chip";
import type { OrderTabId } from "@/features/merchant/orders/lib/order-tabs";
import type { ReactNode } from "react";

import { Link } from "@tanstack/react-router";

import { Widget } from "./overview-analytics";

import {
  ChevronRightIcon,
  ClockIcon,
  GiftIcon,
  PayLaterIcon,
  PickupIcon,
  RequestsIcon,
  StatusDangerIcon,
} from "@/components/icons";
import { StatCard } from "@/components/stat-card";
import { StatusChip } from "@/components/status-chip";

export interface TaskTile {
  id: TodayTaskId;
  /** The M03 tab the tile opens; null when the count is 0 (no link into an empty tab). */
  tab: OrderTabId | null;
  title: string;
  /** Only the alert rows (overdue, owing) carry a hint. */
  hint: string;
  count: number;
  /** Accessible name with the count in words: "Awaiting confirmation, 3 orders". */
  label: string;
}

export interface CollectPart {
  id: CollectStatus;
  label: string;
  amount: string;
  orders: string;
  /** Share of the total, 0–1. */
  share: number;
}

export interface PickupRow {
  id: string;
  reference: string;
  guestName: string;
  gift: string;
  isToday: boolean;
  /** Date tile parts: "Wed", "14", "Oct" ("Today" instead of the weekday). */
  day: { weekday: string; day: string; month: string };
  status: { text: string; tone: StatusTone };
}

export interface MerchantTodayProps {
  title: string;
  date: string;
  todayHeading: string;
  tasksHeading: string;
  attentionHeading: string;
  tiles: TaskTile[];
  collect: {
    title: string;
    total: string;
    hint: string;
    none: string;
    parts: CollectPart[];
  };
  pickups: {
    title: string;
    allLabel: string;
    empty: string;
    rows: PickupRow[];
  };
  empty: { message: string; actionLabel: string };
  isLoading: boolean;
  /** The analytics section under the Today part (step 1.9s). */
  analytics: ReactNode;
  /** Tour work (step 2.10), last in the Today part; tour money stays separate from gifts. */
  tours?: ReactNode;
}

const taskIcon: Record<TodayTaskId, IconComponent> = {
  "awaiting-confirmation": RequestsIcon,
  "awaiting-payment": ClockIcon,
  "to-prepare": GiftIcon,
  ready: PickupIcon,
  overdue: StatusDangerIcon,
  owing: PayLaterIcon,
};

/** The tab each slice of "still to collect" opens. */
const collectTab: Record<CollectStatus, OrderTabId> = {
  accepted: "awaiting-payment",
  preparing: "preparing",
  ready: "ready",
  handed_over: "owing",
};

/** Each stage in the colour of its status chip (owner 15.10.2026), not shades of one red. */
const collectShade: Record<CollectStatus, string> = {
  accepted: "bg-(--status-warning-fill)",
  preparing: "bg-(--status-info-fill)",
  ready: "bg-(--status-success-fill)",
  handed_over: "bg-(--status-warning-fill)",
};

const cellLink =
  "outline-none hover:bg-surface-secondary/50 focus-visible:focus-ring focus-visible:ring-inset";

/** A "To do" tile: a stat card with icon, name and count. Opens M03 on its tab; a tile at 0 is plain text. */
export function Tile({ id, tab, title, count, label }: TaskTile) {
  return (
    <StatCard
      isLarge
      as={({ className, children }) =>
        tab ? (
          <Link
            aria-label={label}
            className={`h-full ${className}`}
            search={{ status: tab }}
            to="/store/orders"
          >
            {children}
          </Link>
        ) : (
          <div
            aria-label={label}
            className={`h-full ${className}`}
            role="group"
          >
            {children}
          </div>
        )
      }
      icon={taskIcon[id]}
      isLink={tab !== null}
      isMuted={!count}
      label={title}
      value={count}
    />
  );
}

/** Overdue and owing: shown above the tiles only when there is something to chase. */
export function AlertRow({ id, tab, title, hint, count, label }: TaskTile) {
  const Icon = taskIcon[id];
  const danger = id === "overdue";

  return (
    <Link
      aria-label={label}
      className={`flex items-center gap-3 px-4 py-3 ${cellLink}`}
      search={{ status: tab ?? undefined }}
      to="/store/orders"
    >
      <span
        aria-hidden
        className={`flex size-9 shrink-0 items-center justify-center rounded-xl ${
          danger
            ? "bg-danger-soft text-danger-soft-foreground"
            : "bg-warning-soft text-warning-soft-foreground"
        }`}
      >
        <Icon size={18} />
      </span>
      <span className="flex min-w-0 flex-1 flex-col">
        <span
          className={`font-semibold ${danger ? "text-danger" : "text-warning"}`}
        >
          {title}
        </span>
        <span className="text-sm text-muted">{hint}</span>
      </span>
      <span
        aria-hidden
        className={`text-2xl font-semibold tabular-nums ${danger ? "text-danger" : "text-warning"}`}
      >
        {count}
      </span>
      <ChevronRightIcon aria-hidden className="shrink-0 text-muted" size={18} />
    </Link>
  );
}

/** Still to collect: the total, one stacked bar by stage, and a legend that links to M03. */
export function CollectWidget({
  title,
  total,
  hint,
  none,
  parts,
}: MerchantTodayProps["collect"]) {
  return (
    <Widget
      className="lg:col-span-2"
      description={parts.length ? hint : none}
      id="today-collect"
      title={title}
    >
      <p className="text-3xl font-semibold tracking-tight tabular-nums">
        {total}
      </p>
      {parts.length > 0 && (
        <>
          <div
            aria-hidden
            className="mt-4 flex h-3 gap-0.5 overflow-hidden rounded-full"
          >
            {parts.map((p) => (
              <span
                key={p.id}
                className={`h-full min-w-1.5 ${collectShade[p.id]}`}
                style={{ flexGrow: p.share, flexBasis: 0 }}
              />
            ))}
          </div>
          <ul className="mt-3 flex flex-col">
            {parts.map((p) => (
              <li key={p.id}>
                <Link
                  className={`-mx-2 flex items-center gap-3 rounded-xl px-2 py-2 ${cellLink}`}
                  search={{ status: collectTab[p.id] }}
                  to="/store/orders"
                >
                  <span
                    aria-hidden
                    className={`size-2.5 shrink-0 rounded-full ${collectShade[p.id]}`}
                  />
                  <span className="flex min-w-0 flex-1 flex-wrap items-baseline gap-x-2">
                    <span className="text-sm font-medium">{p.label}</span>{" "}
                    <span className="text-xs text-muted">{p.orders}</span>
                  </span>
                  <span className="shrink-0 text-sm font-medium tabular-nums">
                    {p.amount}
                  </span>
                </Link>
              </li>
            ))}
          </ul>
        </>
      )}
    </Widget>
  );
}

/** Next pickups: ready and preparing orders by pickup date; each row opens M04. */
export function PickupsWidget({
  title,
  allLabel,
  empty,
  rows,
}: MerchantTodayProps["pickups"]) {
  return (
    <Widget
      actions={
        rows.length > 0 && (
          <Link
            className="inline-flex h-8 shrink-0 items-center gap-0.5 rounded-md text-xs font-medium text-muted outline-none hover:text-foreground focus-visible:focus-ring active:opacity-60"
            to="/store/orders"
          >
            {allLabel}
            <ChevronRightIcon aria-hidden size={14} />
          </Link>
        )
      }
      className="lg:col-span-3"
      id="today-pickups"
      title={title}
    >
      {rows.length ? (
        <ul className="-mx-2 -my-1.5 flex flex-col">
          {rows.map((r) => (
            <li key={r.id}>
              <Link
                className={`flex items-center gap-3 rounded-2xl px-2 py-2.5 ${cellLink}`}
                params={{ orderId: r.id }}
                to="/store/orders/$orderId"
              >
                <span
                  className={`flex w-12 shrink-0 flex-col items-center rounded-xl py-1.5 ${
                    r.isToday
                      ? "bg-foreground text-background"
                      : "bg-surface-secondary"
                  }`}
                >
                  <span className="text-xs leading-4 font-medium">
                    {r.day.weekday}
                  </span>
                  <span className="text-lg leading-6 font-semibold tabular-nums">
                    {r.day.day}
                  </span>
                  <span className="text-xs leading-4">{r.day.month}</span>
                </span>
                <span className="flex min-w-0 flex-1 flex-col gap-1 xl:flex-row xl:items-center xl:gap-3">
                  <span className="flex min-w-0 flex-1 flex-col">
                    <span className="truncate font-medium">
                      {r.guestName}{" "}
                      <span className="ms-1 text-xs font-normal text-muted">
                        {r.reference}
                      </span>
                    </span>
                    <span className="truncate text-sm text-muted">
                      {r.gift}
                    </span>
                  </span>
                  <span className="max-w-full self-start xl:self-center">
                    <StatusChip tone={r.status.tone}>
                      {r.status.text}
                    </StatusChip>
                  </span>
                </span>
                <ChevronRightIcon
                  aria-hidden
                  className="shrink-0 text-muted"
                  size={18}
                />
              </Link>
            </li>
          ))}
        </ul>
      ) : (
        <p className="text-sm text-muted">{empty}</p>
      )}
    </Widget>
  );
}

