/** Phones: one divided list. Rows open nothing; the partner sees no order detail. */
function StackedRows({
  rows,
  label,
  columns,
}: {
  rows: ReportRowView[];
  label: string;
  columns: PartnerReportProps["copy"]["columns"];
}) {
  return (
